(()=>{
const q=s=>document.querySelector(s),qa=s=>[...document.querySelectorAll(s)],pref=matchMedia('(prefers-reduced-motion: reduce)'),fine=matchMedia('(hover:hover) and (pointer:fine)');let paused=pref.matches;
const toggle=document.createElement('button');toggle.id='motion-toggle';toggle.type='button';q('.experience-controls').append(toggle);
function applyMotion(){document.body.classList.toggle('motion-paused',paused);toggle.textContent=paused?'Motion off':'Motion on';toggle.setAttribute('aria-pressed',String(!paused));if(paused)document.getAnimations().forEach(a=>{if(a.effect?.target?.closest?.('main'))a.cancel()});schedule()}
toggle.onclick=()=>{paused=!paused;applyMotion()};pref.addEventListener('change',()=>{paused=pref.matches;applyMotion()});
const hero=q('.hero');hero.insertAdjacentHTML('beforeend','<div class="hero-aura" aria-hidden="true"></div><div class="arrival-lines" aria-hidden="true"><i></i><i></i><i></i></div>');
const h=q('h1');h.setAttribute('aria-label',h.textContent);h.innerHTML='<span class="title-mask"><span>A little escape.</span></span><span class="title-mask"><span>A lasting <em>impression.</em></span></span>';
const titleObserver=new MutationObserver(()=>{if(!q('.arrival:not(.departing)')){hero.classList.add('has-arrived');titleObserver.disconnect()}});titleObserver.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['class']});if(!q('.arrival'))hero.classList.add('has-arrived');
// A continuous progress ring and a frame that opens with the guest's scroll.
q('.journey-stage').insertAdjacentHTML('beforeend','<div class="chapter-meter" aria-hidden="true"><svg viewBox="0 0 100 100"><circle class="ring-base" cx="50" cy="50" r="44"/><circle class="ring-fill" cx="50" cy="50" r="44"/></svg><span>01</span></div>');
const journey=q('.journey'),title=q('#scene-title');new MutationObserver(()=>{q('.chapter-meter span').textContent=String(qa('[data-scene]').findIndex(b=>b.classList.contains('active'))+1).padStart(2,'0');document.dispatchEvent(new CustomEvent('delacruxe:scene'));}).observe(title,{childList:true});
const interlude=document.createElement('section');interlude.className='slow-moment';interlude.setAttribute('aria-label','An evening at your own pace');interlude.innerHTML='<div class="slow-frame"><img src="assets/garden.webp" alt="Outdoor seating beneath softly lit trees at the hotel" loading="lazy"><div class="slow-shade"></div><div class="slow-copy"><span class="eyebrow">THE LUXURY OF A LITTLE TIME</span><h2>Nothing to rush.<br><em>Nowhere else to be.</em></h2><p>Find your corner. Let the evening unfold.</p><a class="text-link" href="#booking">Make time for a stay ↗</a></div><span class="slow-number" aria-hidden="true">D / C</span></div>';
q('#experience').after(interlude);
const ribbon=document.createElement('div');ribbon.className='motion-ribbon';ribbon.setAttribute('aria-hidden','true');ribbon.innerHTML='<div>'+Array(4).fill('<span>ARRIVE <i>✦</i> EXHALE <i>✦</i> STAY A LITTLE LONGER <i>✦</i> </span>').join('')+'</div>';q('#stay').after(ribbon);
// Animate each setting as a single composition; no layout shifts or delayed clicks.
qa('[data-stay]').forEach(b=>b.addEventListener('click',()=>{if(paused)return;q('#stay-image').animate([{clipPath:'inset(0 100% 0 0)',transform:'scale(1.06)'},{clipPath:'inset(0)',transform:'scale(1)'}],{duration:800,easing:'cubic-bezier(.16,1,.3,1)'});document.dispatchEvent(new CustomEvent('delacruxe:stay'))}));
qa('dialog').forEach(d=>new MutationObserver(()=>{if(d.open&&!paused){d.animate([{opacity:0,transform:'translateY(22px) scale(.97)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:550,easing:'cubic-bezier(.16,1,.3,1)'});const img=d.querySelector('img');if(img)img.animate([{clipPath:'inset(0 0 100% 0)'},{clipPath:'inset(0)'}],{duration:750,easing:'cubic-bezier(.16,1,.3,1)'})}}).observe(d,{attributes:true,attributeFilter:['open']}));
qa('[data-detail]').forEach(b=>b.addEventListener('click',()=>{if(!paused)q('#room-detail').animate([{opacity:.2,transform:'translateY(8px)'},{opacity:1,transform:'none'}],{duration:350})}));
qa('.room-wrap').forEach(card=>{card.addEventListener('pointermove',e=>{if(paused||!fine.matches)return;const r=card.getBoundingClientRect();card.style.setProperty('--rx',((e.clientY-r.top)/r.height-.5)*-3+'deg');card.style.setProperty('--ry',((e.clientX-r.left)/r.width-.5)*3+'deg')});card.addEventListener('pointerleave',()=>{card.style.setProperty('--rx','0deg');card.style.setProperty('--ry','0deg')})});
qa('.button').forEach(b=>b.addEventListener('pointermove',e=>{if(paused||!fine.matches)return;const r=b.getBoundingClientRect();b.style.setProperty('--light-x',(e.clientX-r.left)+'px');b.style.setProperty('--light-y',(e.clientY-r.top)+'px')}));
let queued=false;const clamp=(v,a=0,b=1)=>Math.max(a,Math.min(b,v));
function paint(){queued=false;if(paused)return;const jr=journey.getBoundingClientRect();if(jr.bottom>0&&jr.top<innerHeight){const p=clamp(-jr.top/(journey.offsetHeight-innerHeight));journey.style.setProperty('--travel',p);journey.style.setProperty('--frame',Math.max(0,1-clamp((innerHeight-jr.top)/innerHeight))*7+'%');q('.ring-fill').style.strokeDashoffset=String(276.46*(1-p))}const r=interlude.getBoundingClientRect();if(r.bottom>0&&r.top<innerHeight){const p=clamp((innerHeight-r.top)/(innerHeight+r.height));interlude.style.setProperty('--opening',clamp((p-.12)*2));interlude.style.setProperty('--slow-y',(p-.5)*36+'px')}const intro=q('.intro').getBoundingClientRect();q('.wordline').style.transform=`translateX(${clamp((innerHeight-intro.top)/(innerHeight+intro.height))*-45}px)`}
function schedule(){if(!queued){queued=true;requestAnimationFrame(paint)}}addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule);applyMotion();
// Only run continuous ambience while its section is visible.
const visible=new IntersectionObserver(es=>es.forEach(e=>e.target.classList.toggle('motion-visible',e.isIntersecting)),{threshold:0});[hero,ribbon,interlude].forEach(e=>visible.observe(e));
})();
